#!/usr/bin/env php
<?php if(PHP_SAPI!=='cli')exit(1);require dirname(__DIR__).'/app/bootstrap.php';$name=trim(readline('Nama: '));$email=mb_strtolower(trim(readline('Email: ')));fwrite(STDOUT,'Kata sandi (minimal 12 karakter): ');system('stty -echo');$password=trim(fgets(STDIN));system('stty echo');fwrite(STDOUT,PHP_EOL);if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12){fwrite(STDERR,"Data tidak valid.\n");exit(1);}try{$q=db()->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'admin')");$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);echo "Admin berhasil dibuat.\n";}catch(Throwable $e){fwrite(STDERR,"Admin gagal dibuat; periksa email dan koneksi database.\n");exit(1);}
